'use client';
/**
 * Growth-of-100 chart. Technique from the line-chart-morph recipe (effects/line-chart-morph): every range is
 * resampled to one shared resolution, so switching presets interpolates DATA VALUES and the y-domain together and
 * the line never tears; gridlines are keyed by value and cross-fade. Here it is multi-series, rebased to the range
 * start, linear (no smoothing that would invent closes), and fed by the dashboard instead of a built-in dataset.
 * Brush drags and key steps are direct manipulation, so they cut instead of tweening.
 */
import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { easeCubicInOut, scaleLinear } from 'd3';
import { duration as D, useElementSize, useStudioMotion } from '../../../motion';
import { fmt } from './data';
import s from './styles.module.css';

export type Transition = 'morph' | 'drag' | 'key' | 'cut';
export interface ChartSeries { key: string; label: string; values: ArrayLike<number>; role: 'fund' | 'comp' | 'pos' }
interface Props { dates: number[]; series: ChartSeries[]; win: readonly [number, number]; transition: Transition }

const N = 640;
const M = { top: 14, bottom: 26, left: 40 };
interface Target { a: number; b: number; lines: Map<string, Float64Array>; lo: number; hi: number }
interface Frame { lines: Map<string, Float64Array>; lo: number; hi: number; e: number; prev: Target | null }

/** Rebase to 100 at index a, then resample [a, b] linearly to N points (exact: a polyline resampled is the same polyline). */
function rebased(values: ArrayLike<number>, a: number, b: number): Float64Array {
  const out = new Float64Array(N);
  const base = values[a];
  for (let k = 0; k < N; k++) {
    const u = a + (k / (N - 1)) * (b - a);
    const i = Math.min(b - 1, Math.floor(u));
    const v = values[i] + (values[i + 1] - values[i]) * (u - i);
    out[k] = (v / base) * 100;
  }
  return out;
}

function domainOf(lines: Iterable<Float64Array>): [number, number] {
  let lo = Infinity, hi = -Infinity;
  for (const l of lines) for (const v of l) { if (v < lo) lo = v; if (v > hi) hi = v; }
  const pad = Math.max(0.6, (hi - lo) * 0.08);
  const d = scaleLinear().domain([lo - pad, hi + pad]).nice(5).domain();
  return [d[0], d[1]];
}

/** Calendar ticks for a trading-day window: weeks for short ranges, then months, quarters, half-years or years. */
function xTicks(dates: number[], a: number, b: number, max: number): { i: number; label: string }[] {
  const out: { i: number; label: string }[] = [];
  if (b - a <= 50) {
    for (let i = a + 1; i <= b; i++) if (new Date(dates[i]).getUTCDay() < new Date(dates[i - 1]).getUTCDay()) out.push({ i, label: fmt.dateShort.format(dates[i]) });
  } else {
    const starts: number[] = [];
    for (let i = a + 1; i <= b; i++) if (new Date(dates[i]).getUTCMonth() !== new Date(dates[i - 1]).getUTCMonth()) starts.push(i);
    for (const step of [1, 3, 6, 12]) {
      const keep = starts.filter((i) => new Date(dates[i]).getUTCMonth() % step === 0);
      if (keep.length <= max || step === 12) {
        for (const i of keep) { const m = new Date(dates[i]).getUTCMonth(); out.push({ i, label: m === 0 ? fmt.year.format(dates[i]) : fmt.month.format(dates[i]) }); }
        break;
      }
    }
  }
  if (out.length <= max) return out;
  const k = Math.ceil(out.length / max);
  return out.filter((_, j) => j % k === 0);
}

export function PerformanceChart({ dates, series, win, transition }: Props) {
  const { reduced, scale } = useStudioMotion();
  const plotRef = useRef<HTMLDivElement>(null);
  const { width, height } = useElementSize(plotRef);
  const [a, b] = win;
  const [active, setActive] = useState<number | null>(null);
  const focused = useRef(false);
  const transitionRef = useRef(transition);
  transitionRef.current = transition;

  const target = useMemo<Target>(() => {
    const lines = new Map(series.map((sr) => [sr.key, rebased(sr.values, a, b)] as const));
    const [lo, hi] = domainOf(lines.values());
    return { a, b, lines, lo, hi };
  }, [series, a, b]);

  const [frame, setFrame] = useState<Frame>(() => ({ lines: target.lines, lo: target.lo, hi: target.hi, e: 1, prev: null }));
  const frameRef = useRef(frame);
  frameRef.current = frame;
  const shown = useRef(target);

  useEffect(() => {
    if (shown.current === target) return;
    const prev = shown.current;
    shown.current = target;
    const rest: Frame = { lines: target.lines, lo: target.lo, hi: target.hi, e: 1, prev: null };
    const dur = D.slow * 0.86 * scale.duration;
    if (transitionRef.current !== 'morph' || reduced || dur < 1) { setFrame(rest); return; }
    setActive(null);
    const from = frameRef.current;
    let raf = 0, t0 = 0;
    const step = (now: number) => {
      if (!t0) t0 = now;
      const p = Math.min(1, (now - t0) / dur);
      if (p >= 1) { setFrame(rest); return; }
      const e = easeCubicInOut(p);
      const lines = new Map<string, Float64Array>();
      for (const [key, to] of target.lines) {
        const f = from.lines.get(key);
        if (!f) { lines.set(key, to); continue; }
        const out = new Float64Array(N);
        for (let k = 0; k < N; k++) out[k] = f[k] + (to[k] - f[k]) * e;
        lines.set(key, out);
      }
      setFrame({ lines, lo: from.lo + (target.lo - from.lo) * e, hi: from.hi + (target.hi - from.hi) * e, e, prev });
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target, reduced, scale.duration]);

  const wide = width >= 560;
  const right = wide ? 132 : 10;
  const innerW = Math.max(0, width - M.left - right);
  const innerH = Math.max(0, height - M.top - M.bottom);
  const ready = innerW > 40 && innerH > 40;
  const y = useMemo(() => scaleLinear().domain([frame.lo, frame.hi]).range([M.top + innerH, M.top]), [frame.lo, frame.hi, innerH]);
  const xs = (k: number) => M.left + (k / (N - 1)) * innerW;
  const xi = (i: number, w: Target | { a: number; b: number } = { a, b }) => M.left + ((i - w.a) / Math.max(1, w.b - w.a)) * innerW;

  const paths = useMemo(() => {
    const out = new Map<string, string>();
    if (!ready) return out;
    for (const [key, arr] of frame.lines) {
      let d = '';
      for (let k = 0; k < N; k++) d += `${k ? 'L' : 'M'}${xs(k).toFixed(1)} ${y(arr[k]).toFixed(1)}`;
      out.set(key, d);
    }
    return out;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [frame.lines, y, innerW, ready]);

  const toTicks = scaleLinear().domain([target.lo, target.hi]).ticks(5);
  const fromTicks = frame.prev && frame.e < 1 ? scaleLinear().domain([frame.prev.lo, frame.prev.hi]).ticks(5) : toTicks;
  const grid = Array.from(new Set([...fromTicks, ...toTicks])).map((v) => ({
    v, o: fromTicks.includes(v) && toTicks.includes(v) ? 1 : toTicks.includes(v) ? frame.e : 1 - frame.e,
  })).filter((t) => t.v >= frame.lo && t.v <= frame.hi);
  const maxX = Math.max(2, Math.floor(innerW / 64));
  const axisSets = [
    ...(frame.prev && frame.e < 1 ? [{ key: 'from', w: frame.prev, o: Math.max(0, 1 - frame.e * 2) }] : []),
    { key: 'to', w: { a, b }, o: frame.prev && frame.e < 1 ? Math.max(0, frame.e * 2 - 1) : 1 },
  ];

  const settled = frame.e === 1;
  const idx = active !== null && settled ? Math.min(b, Math.max(a, active)) : null;
  const read = idx ?? b;
  const val = (sr: ChartSeries, i: number) => (sr.values[i] / sr.values[a]) * 100;
  const fund = series.find((x) => x.role === 'fund')!;
  const comp = series.find((x) => x.role === 'comp')!;
  const valueText = (i: number) =>
    `${fmt.dateLong.format(dates[i])}: ${series.map((sr) => `${sr.label} ${fmt.index.format(val(sr, i))}`).join(', ')}. Fund minus composite ${fmt.pp(val(fund, i) - val(comp, i))}.`;

  const onPointer = (ev: PointerEvent<HTMLDivElement>) => {
    const r = ev.currentTarget.getBoundingClientRect();
    const u = Math.min(1, Math.max(0, (ev.clientX - r.left - M.left) / Math.max(1, innerW)));
    setActive(a + Math.round(u * (b - a)));
  };
  const onKey = (ev: KeyboardEvent<HTMLDivElement>) => {
    if (ev.key === 'Escape') { setActive(null); return; }
    const cur = active ?? b;
    const next = ev.key === 'ArrowLeft' || ev.key === 'ArrowDown' ? cur - 1 : ev.key === 'ArrowRight' || ev.key === 'ArrowUp' ? cur + 1
      : ev.key === 'PageDown' ? cur - 5 : ev.key === 'PageUp' ? cur + 5 : ev.key === 'Home' ? a : ev.key === 'End' ? b : null;
    if (next === null) return;
    ev.preventDefault();
    setActive(Math.min(b, Math.max(a, next)));
  };

  // Direct end labels, pushed apart so they never overlap.
  const ends = series.map((sr) => {
    const arr = frame.lines.get(sr.key);
    const v = arr ? arr[N - 1] : 100;
    return { sr, v, y: ready ? y(v) : 0 };
  }).sort((p, q) => p.y - q.y);
  for (let k = 1; k < ends.length; k++) if (ends[k].y - ends[k - 1].y < 30) ends[k].y = ends[k - 1].y + 30;
  const overflow = ends.length ? ends[ends.length - 1].y - (M.top + innerH) : 0;
  if (overflow > 0) ends.forEach((e) => { e.y -= overflow; });

  const order: ChartSeries['role'][] = ['comp', 'pos', 'fund'];
  const cx = idx === null ? 0 : xi(idx);

  return (
    <div ref={plotRef} className={s.plot}>
      {ready && (
        <svg width={width} height={height} aria-hidden="true" className={s.svg}>
          {grid.map((t) => (
            <g key={t.v} transform={`translate(0 ${y(t.v).toFixed(1)})`} opacity={t.o}>
              <line x1={M.left} x2={M.left + innerW} className={t.v === 100 ? s.ref : s.grid} />
              <text x={M.left - 8} y={4} textAnchor="end" className={s.tick}>{fmt.int.format(t.v)}</text>
            </g>
          ))}
          {axisSets.map((set) => (
            <g key={set.key} opacity={set.o}>
              {xTicks(dates, set.w.a, set.w.b, maxX).map((t) => {
                const x = xi(t.i, set.w);
                return (
                  <g key={t.i} transform={`translate(${x.toFixed(1)} ${M.top + innerH})`}>
                    <line y2={5} className={s.axisTick} />
                    <text y={18} textAnchor={x < M.left + 18 ? 'start' : x > M.left + innerW - 18 ? 'end' : 'middle'} className={s.tick}>{t.label}</text>
                  </g>
                );
              })}
            </g>
          ))}
          <line x1={M.left} x2={M.left + innerW} y1={M.top + innerH} y2={M.top + innerH} className={s.axisLine} />
          {order.flatMap((role) => series.filter((sr) => sr.role === role)).map((sr) => (
            <path key={sr.key} d={paths.get(sr.key) ?? ''} className={s.line} data-role={sr.role} />
          ))}
          {wide && ends.map((e) => (
            <g key={e.sr.key} transform={`translate(${M.left + innerW + 10} ${e.y.toFixed(1)})`} className={s.endLabel} data-role={e.sr.role}>
              <text y={-3} className={s.endName}>{e.sr.label}</text>
              <text y={11} className={s.endValue}>{fmt.index.format(e.v)}</text>
            </g>
          ))}
          {idx !== null && (
            <g>
              <line x1={cx} x2={cx} y1={M.top} y2={M.top + innerH} className={s.crosshair} />
              {series.map((sr) => <circle key={sr.key} cx={cx} cy={y(val(sr, idx))} r={sr.role === 'fund' ? 4.5 : 3.5} className={s.dot} data-role={sr.role} />)}
            </g>
          )}
        </svg>
      )}
      {idx !== null && ready && (
        <div className={s.tip} data-side={cx > M.left + innerW * 0.6 ? 'left' : 'right'} style={{ transform: `translate(${cx}px, ${M.top + 4}px)` }} aria-hidden="true">
          <div>
            <p className={s.tipDate}>{fmt.dateLong.format(dates[idx])}</p>
            {series.map((sr) => (
              <p key={sr.key} className={s.tipRow} data-role={sr.role}><span className={s.swatch} data-role={sr.role} />{sr.label}<strong>{fmt.index.format(val(sr, idx))}</strong></p>
            ))}
            <p className={s.tipRow}>Fund − composite<strong>{fmt.pp(val(fund, idx) - val(comp, idx))}</strong></p>
          </div>
        </div>
      )}
      <div
        className={s.hit}
        role="slider"
        tabIndex={0}
        aria-label="Inspect daily closes. Left and right arrows step one trading day, Page Up and Page Down a week, Escape hides the readout."
        aria-valuemin={1}
        aria-valuemax={b - a + 1}
        aria-valuenow={read - a + 1}
        aria-valuetext={valueText(read)}
        onPointerMove={onPointer}
        onPointerDown={onPointer}
        onPointerLeave={() => { if (!focused.current) setActive(null); }}
        onFocus={() => { focused.current = true; setActive((x) => x ?? b); }}
        onBlur={() => { focused.current = false; setActive(null); }}
        onKeyDown={onKey}
      />
    </div>
  );
}

'use client';
/**
 * Three-year overview with a brushable window. Technique from the brush-linked-range recipe
 * (effects/brush-linked-range): the brush is hand-built so the window and both handles are real role="slider"
 * controls with date valuetext, pointer capture drives drags, and a click on the strip recentres the window.
 * Here the window is controlled by the dashboard (presets, KPIs, allocation and chart all follow it).
 */
import { useMemo, useRef, type KeyboardEvent, type PointerEvent } from 'react';
import { scaleLinear } from 'd3';
import { useElementSize } from '../../../motion';
import { fmt } from './data';
import s from './styles.module.css';

type Part = 'start' | 'end' | 'window';
interface Props {
  dates: number[];
  values: ArrayLike<number>;
  win: readonly [number, number];
  minSpan: number;
  describedBy: string;
  onChange: (w: [number, number], via: 'drag' | 'key') => void;
  onCommit: () => void;
}

export function RangeBrush({ dates, values, win, minSpan, describedBy, onChange, onCommit }: Props) {
  const stripRef = useRef<HTMLDivElement>(null);
  const { width: sw, height: sh } = useElementSize(stripRef);
  const n = dates.length;
  const drag = useRef<{ part: Part; x: number; win: readonly [number, number] } | null>(null);
  const sx = useMemo(() => scaleLinear().domain([0, n - 1]).range([0, sw]), [n, sw]);

  const path = useMemo(() => {
    if (sw <= 0 || sh <= 0) return '';
    let lo = Infinity, hi = -Infinity;
    for (let i = 0; i < n; i++) { lo = Math.min(lo, values[i]); hi = Math.max(hi, values[i]); }
    const sy = scaleLinear().domain([lo, hi]).range([sh - 6, 6]);
    let d = '';
    for (let i = 0; i < n; i++) d += `${i ? 'L' : 'M'}${sx(i).toFixed(1)} ${sy(values[i]).toFixed(1)}`;
    return d;
  }, [values, n, sx, sw, sh]);

  const years = useMemo(() => {
    const out: { i: number; label: string }[] = [];
    for (let i = 1; i < n; i++) if (new Date(dates[i]).getUTCFullYear() !== new Date(dates[i - 1]).getUTCFullYear()) out.push({ i, label: fmt.year.format(dates[i]) });
    return out;
  }, [dates, n]);
  const quarters = useMemo(() => {
    const out: number[] = [];
    for (let i = 1; i < n; i++) { const m = new Date(dates[i]).getUTCMonth(); if (m % 3 === 0 && m !== new Date(dates[i - 1]).getUTCMonth()) out.push(i); }
    return out;
  }, [dates, n]);

  const apply = (part: Part, base: readonly [number, number], delta: number): [number, number] => {
    const d = Math.round(delta);
    if (part === 'start') return [Math.min(base[1] - minSpan, Math.max(0, base[0] + d)), base[1]];
    if (part === 'end') return [base[0], Math.max(base[0] + minSpan, Math.min(n - 1, base[1] + d))];
    const span = base[1] - base[0];
    const a = Math.min(n - 1 - span, Math.max(0, base[0] + d));
    return [a, a + span];
  };
  const onDown = (part: Part) => (ev: PointerEvent<HTMLDivElement>) => {
    if (ev.button !== 0) return;
    ev.stopPropagation();
    ev.currentTarget.setPointerCapture(ev.pointerId);
    drag.current = { part, x: ev.clientX, win };
  };
  const onMove = (ev: PointerEvent<HTMLDivElement>) => {
    const g = drag.current;
    if (!g || sw <= 0) return;
    const next = apply(g.part, g.win, ((ev.clientX - g.x) / sw) * (n - 1));
    if (next[0] !== win[0] || next[1] !== win[1]) onChange(next, 'drag');
  };
  const onUp = () => { if (drag.current) { drag.current = null; onCommit(); } };
  const onKey = (part: Part) => (ev: KeyboardEvent<HTMLDivElement>) => {
    const big = ev.shiftKey ? 5 : 1;
    const d = ev.key === 'ArrowLeft' || ev.key === 'ArrowDown' ? -big : ev.key === 'ArrowRight' || ev.key === 'ArrowUp' ? big
      : ev.key === 'PageDown' ? -5 : ev.key === 'PageUp' ? 5 : ev.key === 'Home' ? -n : ev.key === 'End' ? n : 0;
    if (!d) return;
    ev.preventDefault();
    onChange(apply(part, win, d), 'key');
  };
  const onTrackDown = (ev: PointerEvent<HTMLDivElement>) => {
    if (ev.button !== 0 || sw <= 0) return;
    const r = ev.currentTarget.getBoundingClientRect();
    const centre = ((ev.clientX - r.left) / r.width) * (n - 1);
    const span = win[1] - win[0];
    const a = Math.min(n - 1 - span, Math.max(0, Math.round(centre - span / 2)));
    onChange([a, a + span], 'drag');
    onCommit();
  };

  const left = sx(win[0]), right = sx(win[1]);
  const text = (i: number) => fmt.dateLong.format(dates[i]);

  return (
    <div className={s.brush}>
      <div ref={stripRef} className={s.strip} onPointerDown={onTrackDown}>
        {sw > 0 && (
          <svg width={sw} height={sh} aria-hidden="true" className={s.svg}>
            {quarters.map((i) => <line key={i} x1={sx(i)} x2={sx(i)} y1={0} y2={sh} className={s.grid} />)}
            <path d={path} className={s.overview} />
          </svg>
        )}
        <div className={s.shade} style={{ left: 0, width: Math.max(0, left) }} />
        <div className={s.shade} style={{ left: right, right: 0 }} />
        <div
          className={s.window}
          style={{ left, width: Math.max(0, right - left) }}
          role="slider" tabIndex={0} aria-label="Move range" aria-describedby={describedBy}
          aria-valuemin={0} aria-valuemax={n - 1 - (win[1] - win[0])} aria-valuenow={win[0]}
          aria-valuetext={`${text(win[0])} to ${text(win[1])}`}
          onPointerDown={onDown('window')} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
          onKeyDown={onKey('window')} onKeyUp={(e) => { if (e.key.startsWith('Arrow') || e.key.startsWith('Page') || e.key === 'Home' || e.key === 'End') onCommit(); }}
        />
        {(['start', 'end'] as const).map((part) => (
          <div
            key={part}
            className={s.handle}
            style={{ left: part === 'start' ? left : right }}
            role="slider" tabIndex={0}
            aria-label={part === 'start' ? 'Range start' : 'Range end'} aria-describedby={describedBy}
            aria-valuemin={part === 'start' ? 0 : win[0] + minSpan}
            aria-valuemax={part === 'start' ? win[1] - minSpan : n - 1}
            aria-valuenow={part === 'start' ? win[0] : win[1]}
            aria-valuetext={text(part === 'start' ? win[0] : win[1])}
            onPointerDown={onDown(part)} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
            onKeyDown={onKey(part)} onKeyUp={(e) => { if (e.key.startsWith('Arrow') || e.key.startsWith('Page') || e.key === 'Home' || e.key === 'End') onCommit(); }}
          ><span /></div>
        ))}
      </div>
      <div className={s.years} aria-hidden="true">
        {years.map((y) => <span key={y.i} style={{ left: sx(y.i) }}>{y.label}</span>)}
      </div>
    </div>
  );
}

/* Fernhollow — an end-of-day ledger terminal. Mono figures, hairline rules, no cards; one warn colour of its own. */
.root {
  --fh-up: var(--s3-accent, #0a6e4d);
  --fh-down: var(--s3-signal, #bf2f09);
  --fh-warn: #8a5a00;
  container-type: inline-size;
  min-height: 100dvh;
  padding-bottom: 64px;
  background: var(--s3-bg, #f3f0e8);
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  font-size: 0.875rem;
  line-height: 1.45;
}
:global([data-theme='dark']) .root { --fh-warn: #f2b632; }
.root[data-gains='red'] { --fh-up: var(--s3-signal, #bf2f09); --fh-down: var(--s3-accent, #0a6e4d); }

.wrap { max-width: 1440px; margin: 0 auto; padding-inline: clamp(16px, 2.4cqi, 32px); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.label { margin: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.sub { margin: 4px 0 0; font-size: 0.78rem; line-height: 1.4; color: var(--s3-ink-muted, #5c5a52); }
.hint { margin: 8px 0 0; font-size: 0.75rem; line-height: 1.4; color: var(--s3-ink-muted, #5c5a52); }
.simTag, .simBadge {
  display: inline-block; padding: 0 5px; border: 1px solid var(--s3-line-strong, #11110f); border-radius: 2px;
  font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.625rem; font-weight: 500; line-height: 1.5;
  letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink, #11110f); white-space: nowrap;
}
.simBadge { background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); border-color: var(--s3-ink, #11110f); }

/* ── status bar ───────────────────────────────────────────────── */
.bar { background: var(--s3-bg, #f3f0e8); border-bottom: 1px solid var(--s3-line-strong, #11110f); }
@container (min-width: 900px) { .bar { position: sticky; top: 44px; z-index: 20; } }
.barInner { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 28px; padding-block: 10px; }
.brand { margin-right: auto; min-width: 0; }
.house { margin: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.fund { margin: 2px 0 0; font-family: var(--s3-font-display, ui-sans-serif, system-ui); font-size: 1.375rem; font-weight: 700; font-stretch: 80%; letter-spacing: -0.02em; line-height: 1.05; }
.fundClass { margin-left: 6px; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 500; letter-spacing: 0.02em; color: var(--s3-ink-muted, #5c5a52); }
.status { display: flex; flex-wrap: wrap; gap: 6px 22px; margin: 0; }
.status div { display: grid; gap: 1px; }
.status dt { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.625rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.status dd { margin: 0; font-size: 0.8125rem; font-variant-numeric: tabular-nums; }

.gains, .ranges { display: inline-flex; align-items: center; gap: 2px; margin: 0; padding: 2px; border: 1px solid var(--s3-line, #11110f24); border-radius: 999px; min-inline-size: 0; }
.gainsLegend { float: left; margin: 0 6px 0 8px; padding: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.625rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.seg { position: relative; display: block; }
.seg input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
.seg > span {
  display: inline-flex; align-items: center; gap: 6px; min-width: 40px; height: 28px; padding: 0 10px; justify-content: center;
  border-radius: 999px; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.02em;
  color: var(--s3-ink-muted, #5c5a52); transition: background-color var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease), color var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease);
}
.seg input:hover + span { color: var(--s3-ink, #11110f); }
.seg input:checked + span { background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); }
.seg input:focus-visible + span { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.segSwatch { width: 8px; height: 8px; border-radius: 50%; }
.segSwatch[data-g='green'] { background: var(--s3-accent, #0a6e4d); }
.segSwatch[data-g='red'] { background: var(--s3-signal, #bf2f09); }
.seg input:checked + span .segSwatch { box-shadow: 0 0 0 1.5px var(--s3-bg, #f3f0e8); }
.custom { display: inline-flex; align-items: center; height: 28px; padding: 0 10px; border-radius: 999px; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.75rem; color: var(--s3-ink-muted, #5c5a52); border: 1px dashed transparent; }
.custom[data-on] { border-color: var(--s3-line-strong, #11110f); color: var(--s3-ink, #11110f); }

.intro { max-width: 78ch; margin: 18px 0 0; font-size: 0.875rem; line-height: 1.5; color: var(--s3-ink-muted, #5c5a52); text-wrap: pretty; }

/* ── attention ────────────────────────────────────────────────── */
.attention { margin-top: 20px; }
.count { margin-left: 8px; color: var(--s3-ink, #11110f); }
.alerts { display: grid; gap: 0; margin: 10px 0 0; padding: 0; list-style: none; border-top: 1px solid var(--s3-line-strong, #11110f); }
@container (min-width: 1080px) { .alerts { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 32px; } }
.alert { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: start; gap: 4px 12px; padding: 12px 0; border-bottom: 1px solid var(--s3-line, #11110f24); }
.alert[data-acked] .alertTitle { color: var(--s3-ink-muted, #5c5a52); }
.alertBody { min-width: 0; }
.alertTitle { margin: 0; font-size: 0.9375rem; font-weight: 600; line-height: 1.3; }
